export type PayrollRunState =
  | "DRAFT"
  | "CALCULATING"
  | "REVIEW"
  | "FINALIZED"
  | "PAID";

// FINALIZED results should normally become immutable.
// Corrections should create explicit adjustments/reversals rather than
// silently rewriting historical payroll evidence.

export type PurchaseOrderState =
  | "DRAFT"
  | "SUBMITTED"
  | "APPROVED"
  | "REJECTED"
  | "CANCELED";

export function canApprovePurchaseOrder(
  state: PurchaseOrderState,
): boolean {
  return state === "SUBMITTED";
}

