// Pseudocode-level example for Phase 36.

async function calculatePayrollJob(runId: string) {
  const run = await loadPayrollRun(runId);

  if (run.status === "FINALIZED" || run.status === "CALCULATED") {
    return run; // durable idempotent result
  }

  await claimRunForCalculation(runId);
  const result = await calculateFromVersionedInputs(runId);
  return persistCalculatedResult(runId, result);
}

declare function loadPayrollRun(id: string): Promise<any>;
declare function claimRunForCalculation(id: string): Promise<void>;
declare function calculateFromVersionedInputs(id: string): Promise<any>;
declare function persistCalculatedResult(id: string, value: any): Promise<any>;
